1	// Query-facing keyboard/application receipts used by the chapter journey probe.
2	// Gameplay never reads this state, so instrumentation cannot steer the story.
3	
4	export interface JourneyInputEvent {
5	  sequence: number;
6	  at: number;
7	  type: 'gameplay-hotkey-boundary' | 'application-submit';
8	  code?: string;
9	  targetEditable?: boolean;
10	  value?: string;
11	}
12	
13	export interface JourneyInputSnapshot {
14	  revision: number;
15	  hotkeyActivations: number;
16	  submitCount: number;
17	  lastSubmittedValue: string | null;
18	  events: JourneyInputEvent[];
19	}
20	
21	const GAMEPLAY_HOTKEY_CODES = new Set([
22	  'KeyW', 'KeyA', 'KeyS', 'KeyD', 'Space', 'ShiftLeft', 'ShiftRight',
23	  'KeyB', 'KeyC', 'KeyF', 'KeyH', 'KeyM', 'KeyR', 'Escape',
24	  'Digit0', 'Digit1', 'Digit2', 'Digit3', 'Digit4',
25	  'Digit5', 'Digit6', 'Digit7', 'Digit8', 'Digit9'
26	]);
27	
28	const MAX_EVENTS = 80;
29	let revision = 0;
30	let hotkeyActivations = 0;
31	let submitCount = 0;
32	let lastSubmittedValue: string | null = null;
33	const events: JourneyInputEvent[] = [];
34	
35	function append(event: Omit<JourneyInputEvent, 'sequence' | 'at'>): void {
36	  revision += 1;
37	  events.push({ sequence: revision, at: Date.now(), ...event });
38	  if (events.length > MAX_EVENTS) events.splice(0, events.length - MAX_EVENTS);
39	}
40	
41	/**
42	 * Records a gameplay shortcut candidate that reached the window-level input
43	 * boundary. Editable controls must stop their keystrokes before this boundary.
44	 */
45	export function recordJourneyGameplayHotkeyBoundary(code: string, targetEditable: boolean): void {
46	  if (!GAMEPLAY_HOTKEY_CODES.has(code)) return;
47	  hotkeyActivations += 1;
48	  append({ type: 'gameplay-hotkey-boundary', code, targetEditable });
49	}
50	
51	/** Records a successful application-level naming submission, not a DOM Enter. */
52	export function recordJourneyInputSubmission(value: string): void {
53	  submitCount += 1;
54	  lastSubmittedValue = value;
55	  append({ type: 'application-submit', value });
56	}
57	
58	export function getJourneyInputSnapshot(): JourneyInputSnapshot {
59	  return {
60	    revision,
61	    hotkeyActivations,
62	    submitCount,
63	    lastSubmittedValue,
64	    events: events.map(event => ({ ...event }))
65	  };
66	}
67	
68	/** Test/probe-run isolation only; ordinary gameplay has no reason to call it. */
69	export function resetJourneyInputRuntime(): void {
70	  revision = 0;
71	  hotkeyActivations = 0;
72	  submitCount = 0;
73	  lastSubmittedValue = null;
74	  events.splice(0, events.length);
75	}
