      log(`${label}: cleanup FAILED (reason=${reason}): ${stopError.split('\n')[0]} — the original outcome is unchanged and still reported`);
    }
  })();
  await stopPromise;
  return { stopped, invoked: true, reason, requests: stopRequests, error: stopError };
},

