python3 - <<'PY'
p='verifier/probes/manual-focused/manual-witness-clearance-probe.mjs'
s=open(p).read()
q='verifier/probes/manual-focused/manual-witness-hold-probe.mjs'
old = """    if ((s2?.anchors ?? []).includes('anc.cg.route-tested')) { tested = true; say(`route-tested reached at +${rec.ms}ms`); break; }
    // An authored short-reference hold is answered with the authored witness verb, not by calling it clearance.
    if (rec.prompts.some((p) => /\\bF\\b/.test(p ?? '')) && (w?.witnessOffered === true)) { await pressF('the shipped witness prompt was offered during W\\'s test'); }
    await sleep(2000);"""
new = r"""    if ((s2?.anchors ?? []).includes('anc.cg.route-tested')) { tested = true; say(`route-tested reached at +${rec.ms}ms`); break; }
    // An authored short-reference hold is answered with the AUTHORED WITNESS
    // VERB at the authored witness point (CG_POSES.W, documented in
    // commonGroundState.ts as "W-7744's inspection pose, and the off-route
    // intermediate witness point"). This is ordinary movement plus the shipped
    // prompt; it is not a body-clearance relabel and grants nothing.
    const objNow = (await readState(page))?.objectiveId ?? null;
    if (objNow === 'ch13:survey:witness' && !witnessTried) {
      witnessTried = true;
      const wpt = [-34, 51.05, 10];
      const legW2 = await walkTo('to-witness-point', wpt, { arrive: 1.0, budgetMs: 60000 });
      const atWit = await snapState('at-witness-point');
      report.witnessLeg = { reached: legW2.reached, finalDistance: legW2.finalDistance, prompts: atWit.prompts, holdReason: atWit.holdReason };
      gate('reached-the-authored-witness-point', legW2.reached === true, report.witnessLeg);
      if ((atWit.prompts ?? []).some((p) => /\bF\b/.test(p ?? ''))) { await pressF('the authored witness prompt at the witness point'); await snapState('after-witness-F'); }
      else say('no F prompt at the witness point; not pressing F');
      continue;
    }
    if (rec.prompts.some((p) => /\bF\b/.test(p ?? '')) && (w?.witnessOffered === true)) { await pressF('the shipped witness prompt was offered during W\'s test'); }
    await sleep(2000);"""
assert old in s
s=s.replace(old,new)
s=s.replace("const tw = Date.now(); const watch = []; let tested = false;","const tw = Date.now(); const watch = []; let witnessTried = false; let tested = false;")
s=s.replace("manual-witness-clearance-probe.mjs","manual-witness-hold-probe.mjs").replace("'witness-1'","'witness-2'")
open(q,'w').write(s)
PY
node verifier/probes/manual-focused/manual-witness-hold-probe.mjs --self-test && date -u +%FT%T && flock -x -w 900 /home/thomasphillip/Projects/Paraform/harness/output/.heavy.lock node verifier/probes/manual-focused/manual-witness-hold-probe.mjs --out witness-2 --watch-ms 110000 > logs/manual-focused/witness-2.log 2>&1; rc=$?; echo "NODE_EXIT=$rc"; date -u +%FT%T; grep -E "GATE (PASS|FAIL) (reached-the-authored|W-actually)|witness|route-tested|verdict|STOP" logs/manual-focused/witness-2.log | tail -20

node verifier/probes/manual-focused/rehash-source.mjs | tee logs/manual-focused/rehash-after.json; echo "rehash_exit=${PIPESTATUS[0]}"; for d in input-gate-1 route-1 corner-1 corner-2 witness-1 witness-2; do echo "== $d"; cat verifier/captures/manual-focused/$d/summary.sha256; python3 -c "
import json;d=json.load(open('verifier/captures/manual-focused/$d/summary.json'))
c=d.get('cleanup') or {}
print(' verdict',d['verdict'],'| renderer',d.get('renderer'),'| headed',d.get('headed'),'| cleanup',c.get('state'),c.get('cleanupCompleted'),'stopsRootPreview',c.get('stopsRootPreview'),'| snapshot',(d.get('sourceSnapshot') or {}).get('manifestSha256','')[:16])
"; done; pgrep -fa "chrome|playwright" | grep -v grep | head

